preConditionHook:
// Two nested Donchian windows, both current-inclusive. The inner one spans
// rangeBars, the outer rangeBars + priorLookback; the long side fires when the
// inner window's highest high is strictly below the outer one's, i.e. the
// market has not made a new high for rangeBars bars -- Brooks's test for a
// pullback that has outgrown its trend and become a trading range.
//
// Both loops mirror EasyLanguage's Extremes(), which Highest()/Lowest() call:
// seeded at bar 0, scanning bars 1..Length-1, strict comparison. Extremes is
// EL SOURCE, so its comparison carries the EL tolerance -- el_gt/el_lt, as in
// Breakout (the reference).
recentHigh = high[0];
recentLow = low[0];
for (int i = 1; i < (int)rangeBars; ++i) {
    if (el_gt(high[i], recentHigh)) recentHigh = high[i];
    if (el_lt(low[i], recentLow)) recentLow = low[i];
}
outerHigh = high[0];
outerLow = low[0];
for (int i = 1; i < (int)(rangeBars + priorLookback); ++i) {
    if (el_gt(high[i], outerHigh)) outerHigh = high[i];
    if (el_lt(low[i], outerLow)) outerLow = low[i];
}
